private void renameDirectory(Path src, Path dst, String srcKey, String dstKey, S3AFileStatus dstStatus) throws IOException {
    if (LOG.isDebugEnabled()) {
        LOG.debug("rename: renaming directory " + src + " to " + dst);
    }
    if (!dstKey.endsWith("/")) {
        dstKey = dstKey + "/";
    }
    if (!srcKey.endsWith("/")) {
