  /**
   * Iterator implementation for listFiles with recursion.
   */
  private static class LocatedFileStatusIterator implements RemoteIterator<LocatedFileStatus> {
    private final FileContext context;
    private final boolean recursive;
    private final Stack<RemoteIterator<LocatedFileStatus>> itors = new Stack<>();
    private RemoteIterator<LocatedFileStatus> curItor;
    private LocatedFileStatus curFile;

    LocatedFileStatusIterator(Path start, boolean recursive, FileContext context) throws IOException {
      this.context = context;
      this.recursive = recursive;
      this.curItor = context.listLocatedStatus(start);
      this.curFile = null;
    }

    @Override
    public boolean hasNext() throws IOException {
      while (curFile == null) {
        if (curItor.hasNext()) {
          handleFileStat(curItor.next());
        } else if (!itors.empty()) {
          curItor = itors.pop();
        } else {
          return false;
        }
      }
      return true;
    }

    private void handleFileStat(LocatedFileStatus stat) throws IOException {
      if (stat.isFile()) {
        curFile = stat;
      } else if (stat.isSymlink()) {
        FileStatus symstat = context.getFileStatus(stat.getSymlink());
        if (symstat.isFile() || (recursive && symstat.isDirectory())) {
          itors.push(curItor);
          curItor = context.listLocatedStatus(stat.getPath());
        }
      } else if (recursive) {
        itors.push(curItor);
        curItor = context.listLocatedStatus(stat.getPath());
      }
    }

    @Override
    public LocatedFileStatus next() throws IOException {
      if (hasNext()) {
        LocatedFileStatus result = curFile;
        curFile = null;
        return result;
      }
      throw new NoSuchElementException("No more entry in " + curItor);
    }
  }
}

