    return perform("authentication",
                   authUri,
                   new AuthenticationPost(authenticationRequest));
  }

  private class AuthenticationPost extends AuthMethodProcessor<AccessToken> {
    final AuthenticationRequest authenticationRequest;

    private AuthenticationPost(AuthenticationRequest authenticationRequest) {
      this.authenticationRequest = authenticationRequest;
    }

    @Override
    protected void setup(AuthPostMethod method) throws IOException {
      method.setRequestEntity(getAuthenticationRequst(authenticationRequest));
    }

    @Override
    protected int[] getAllowedStatusCodes() {
      return new int[]{
        SC_OK,
        SC_BAD_REQUEST,
        SC_CREATED,
        SC_ACCEPTED,
        SC_NON_AUTHORITATIVE_INFORMATION,
        SC_NO_CONTENT,
        SC_RESET_CONTENT,
        SC_PARTIAL_CONTENT,
        SC_MULTI_STATUS,
        SC_UNAUTHORIZED
      };
    }

    @Override
    public AccessToken extractResult(AuthPostMethod method) throws IOException {
      if (method.getStatusCode() == SC_BAD_REQUEST) {
        throw new SwiftAuthenticationFailedException(
          authenticationRequest.toString(), "POST", authUri, method);
      }

      AuthenticationResponse access =
        JSONUtil.toObject(method.getResponseBodyAsString(),
                          AuthenticationWrapper.class).getAccess();
      List<Catalog> serviceCatalog = access.getServiceCatalog();
      Endpoint swiftEndpoint = findSwiftEndpoint(serviceCatalog);
      if (swiftEndpoint == null) {
        throw new SwiftInvalidResponseException(buildCatalogErrorMessage(serviceCatalog),
                                                SC_OK,
                                                "authenticating",
                                                authUri);
      }

      URI endpointURI = usePublicURL ? swiftEndpoint.getPublicURL() : swiftEndpoint.getInternalURL();
      URI objectLocation = buildObjectLocationURI(endpointURI, swiftEndpoint);
      AccessToken accessToken = access.getToken();
      setAuthDetails(endpointURI, objectLocation, accessToken);

      if (LOG.isDebugEnabled()) {
        LOG.debug("authenticated against " + endpointURI);
      }
      createDefaultContainer();
      return accessToken;
    }
  }

  private Endpoint findSwiftEndpoint(List<Catalog> catalogs) {
    for (Catalog catalog : catalogs) {
      String name = catalog.getName();
      String type = catalog.getType();
      if (SERVICE_CATALOG_SWIFT.equals(name) || SERVICE_CATALOG_CLOUD_FILES.equals(name) || SERVICE_CATALOG_OBJECT_STORE.equals(type)) {
        for (Endpoint endpoint : catalog.getEndpoints()) {
          String endpointRegion = endpoint.getRegion();
          if (region == null || region.equals(endpointRegion)) {
            return endpoint;
          }
        }
      }
    }
    return null;
  }

  private URI buildObjectLocationURI(URI endpointURI, Endpoint swiftEndpoint) throws SwiftException {
    String path = SWIFT_OBJECT_AUTH_ENDPOINT + swiftEndpoint.getTenantId();
    String host = endpointURI.getHost();
    try {
      return new URI(endpointURI.getScheme(), null, host, endpointURI.getPort(), path, null, null);
    } catch (URISyntaxException e) {
      throw new SwiftException("object endpoint URI is incorrect: " + endpointURI + " + " + path, e);
    }
  }

  private String buildCatalogErrorMessage(List<Catalog> catalogs) {
    StringBuilder catList = new StringBuilder();
    StringBuilder regionList = new StringBuilder();
    for (Catalog catalog : catalogs) {
      String name = catalog.getName();
      String type = catalog.getType();
      catList.append(String.format("[%s: %s]; ", name, type));
      for (Endpoint endpoint : catalog.getEndpoints()) {
        String endpointRegion = endpoint.getRegion();
        regionList.append(String.format("[%s => %s / %s]; ", endpointRegion, endpoint.getPublicURL(), endpoint.getInternalURL()));
      }
    }
    return "Could not find swift service from auth URL " + authUri + " and region '" + region + "'. Categories: " + catList + ((regionList.length() > 0) ? ("regions: " + regionList) : "No regions");
  }

