  private void handleCreateContainerStatus(int status) throws IOException {
    if (status == SC_BAD_REQUEST) {
      throw new SwiftBadRequestException(
        "Bad request -authentication failure or bad container name?",
        status,
        "PUT",
        null);
    }
    if (!isStatusCodeExpected(status,
            SC_OK,
            SC_CREATED,
            SC_ACCEPTED,
            SC_NO_CONTENT)) {
      throw new SwiftInvalidResponseException("Couldn't create container "
              + container +
              " for storing data in Swift. Try to create container "
              + container + " manually ",
              status,
              "PUT",
              null);
    }
