  private <M extends HttpMethod, R> R perform(URI uri,
                      HttpMethodProcessor<M, R> processor)
    throws IOException,
           SwiftBadRequestException,
           SwiftInternalStateException,
           SwiftInvalidResponseException,
           FileNotFoundException {
    return perform("",uri, processor);
  }

  private <M extends HttpMethod, R> R perform(String reason,
                                              URI uri,
                                              HttpMethodProcessor<M, R> processor)
      throws IOException, SwiftBadRequestException, SwiftInternalStateException,
            SwiftInvalidResponseException, FileNotFoundException {
    checkNotNull(uri);
    checkNotNull(processor);

    final M method = processor.createMethod(uri.toString());
    setMethodParams(method);
    method.addRequestHeader(HEADER_USER_AGENT, SWIFT_USER_AGENT);
    Duration duration = new Duration();
    boolean success = false;
    try {
      int statusCode = exec(method);
      validateStatusCode(method, statusCode, processor.getAllowedStatusCodes());
      R result = processor.extractResult(method);
      success = true;
      return result;
    } catch (IOException e) {
      method.releaseConnection();
      throw e;
    } finally {
      duration.finished();
      durationStats.add(method.getName()+" " + reason, duration, success);
    }
  }

  private void validateStatusCode(HttpMethod method, int statusCode, int[] allowedStatusCodes) throws IOException {
    if (!isStatusCodeExpected(statusCode, allowedStatusCodes)) {
      throw buildException(method, statusCode);
    }
  }

  private IOException buildException(HttpMethod method, int statusCode) {
    URI uri = method.getURI();
    String errorMessage = String.format("Method %s on %s failed, status code: %d, status line: %s",
            method.getName(), uri, statusCode, method.getStatusLine());
    if (LOG.isDebugEnabled()) {
      LOG.debug(errorMessage);
    }
    switch (statusCode) {
      case SC_NOT_FOUND:
        return new FileNotFoundException("Operation " + method.getName() + " on " + uri);
      case SC_BAD_REQUEST:
        return new SwiftBadRequestException("Bad request against " + uri, method.getName(), uri, method);
      case SC_REQUESTED_RANGE_NOT_SATISFIABLE:
        return buildEOFException(method);
      case SC_UNAUTHORIZED:
        return new SwiftAuthenticationFailedException("Operation not authorized- current access token =" + getToken(), method.getName(), uri, method);
      case SC_TOO_MANY_REQUESTS_429:
      case SC_THROTTLED_498:
        return new SwiftThrottledRequestException("Client is being throttled: too many requests", method.getName(), uri, method);
      default:
        return new SwiftInvalidResponseException(errorMessage, method.getName(), uri, method);
    }
  }

  private IOException buildEOFException(HttpMethod method) {
    StringBuilder errorText = new StringBuilder(method.getStatusText());
    Header requestContentLen = method.getRequestHeader(HEADER_CONTENT_LENGTH);
    if (requestContentLen != null) {
      errorText.append(" requested ").append(requestContentLen.getValue());
    }
    Header availableContentRange = method.getResponseHeader(HEADER_CONTENT_RANGE);
    if (availableContentRange != null) {
      errorText.append(" available ").append(availableContentRange.getValue());
    }
    return new EOFException(errorText.toString());
  }

  private <M extends HttpMethod> int exec(M method) throws IOException {
    final HttpClient client = new HttpClient();
    if (proxyHost != null) {
      client.getParams().setParameter(ConnRoutePNames.DEFAULT_PROXY,
              new HttpHost(proxyHost, proxyPort));
    }

    int statusCode = execWithDebugOutput(method, client);

    if (isAuthFailure(statusCode, method)) {
      handleAuthFailure(method);
      statusCode = execWithDebugOutput(method, client);
    }

    if (statusCode == HttpStatus.SC_UNAUTHORIZED) {
      handleUnauthorized(method);
      statusCode = execWithDebugOutput(method, client);
    }
    return statusCode;
  }

  private <M extends HttpMethod> boolean isAuthFailure(int statusCode, M method) {
    return (statusCode == HttpStatus.SC_UNAUTHORIZED || statusCode == HttpStatus.SC_BAD_REQUEST)
            && method instanceof AuthPostMethod
            && !useKeystoneAuthentication;
  }

  private void handleAuthFailure(AuthPostMethod method) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Operation failed with status " + method.getStatusCode() +
               " attempting keystone auth");
    }
    useKeystoneAuthentication = true;
    method.setRequestEntity(getAuthenticationRequst(keystoneAuthRequest));
  }

  private void handleUnauthorized(HttpMethod method) throws IOException {
    if (method instanceof AuthPostMethod) {
      throw new SwiftAuthenticationFailedException(authRequest.toString(),
                                                   "auth",
                                                   authUri,
                                                   method);
    }
    if (LOG.isDebugEnabled()) {
      LOG.debug("Reauthenticating");
    }
    authenticate();
    if (LOG.isDebugEnabled()) {
      LOG.debug("Retrying original request");
    }
  }

  private <M extends HttpMethod> void setMethodParams(M method) {
