private void handleAuthFailure(AuthPostMethod method) throws IOException {
  if (LOG.isDebugEnabled()) {
    LOG.debug("Operation failed with status " + method.getStatusCode() + " attempting keystone auth");
  }
  useKeystoneAuthentication = true;
  method.setRequestEntity(getAuthenticationRequst(keystoneAuthRequest));
}
