	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		checkJavaVersion();

		MainOptions options = parseCommandLine(args);

		if(options.settingsDirectory != null && options.portFile != null)
			options.portFile = MiscUtilities.constructPath(options.settingsDirectory,options.portFile);
		else
			options.portFile = null;

		Log.init(true,options.level);

		connectToServer(options);

		showSplashIfNeeded(options.settingsDirectory);

		Writer stream = initSettingsDirectory(options.settingsDirectory);

		Log.setLogWriter(stream);

		Log.log(Log.NOTICE,jEdit.class,"jEdit version " + getVersion());
		Log.log(Log.MESSAGE,jEdit.class,"Settings directory is "
			+ options.settingsDirectory);

		initServer(options.portFile);

		initMisc();
		initSystemProperties();
		if(jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();

		BeanShell.init();

		initUserProperties();
		initPLAF();

		initJava14();

		initActions();
		initDockables();

		GUIUtilities.advanceSplashProgress();

		VFSManager.init();

		if(!options.noPlugins)
			initPlugins();

		loadHistoryAndRecent(options.settingsDirectory);

		GUIUtilities.advanceSplashProgress();

		sortBuffers = getBooleanProperty("sortBuffers");
		sortByName = getBooleanProperty("sortByName");

		reloadModes();

		GUIUtilities.advanceSplashProgress();

		SearchAndReplace.load();

		GUIUtilities.advanceSplashProgress();

		startPlugins();

		loadMacrosAndScripts(options.noStartupScripts, options.jEditHome != null, options.settingsDirectory != null);

		runScriptIfSpecified(options.scriptFile, options.userDir);

		propertiesChanged();

		GUIUtilities.advanceSplashProgress();

		Buffer buffer = openFiles(null, options.userDir, args);
		if(buffer != null)
		{
			// files specified on command line; force initial view
			// to open
			options.gui = true;
		}

		String splitConfig = null;

		if(options.restore && options.settingsDirectory != null
			&& jEdit.getBooleanProperty("restore")
			&& (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			splitConfig = restoreOpenFiles();
		}

		if(bufferCount == 0 && options.gui)
			newFile(null);

		createViewAndHideSplash(buffer, splitConfig, options.gui);
	} //}}}

	//{{{ MainOptions class
	private static class MainOptions
	{
