				.startAllPlugins();
		}
	} //}}}

	//{{{ runStartupScriptsIfNeeded() helper
	private static void runStartupScriptsIfNeeded(boolean noStartupScripts,
		String jEditHome, String settingsDirectory)
	{
		if(!noStartupScripts && jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome,"startup");
			File file = new File(path);
			if(file.exists())
