	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		checkJavaVersion();

		int level = parseLogLevel(args);

		Settings settings = parseSettings(args);

		Log.init(true, level);

		connectToServer(settings);

		if (!new File(settings.settingsDirectory, "nosplash").exists())
			GUIUtilities.showSplashScreen();

		initSettingsDirectory(settings);

		Log.setLogWriter(settings.logWriter);

		Log.log(Log.NOTICE, jEdit.class, "jEdit version " + getVersion());
		Log.log(Log.MESSAGE, jEdit.class, "Settings directory is "
			+ settings.settingsDirectory);

		initServer(settings);

		startInitialization(settings);

		startPlugins();

		loadMacrosAndScripts(settings);

		runScriptIfSpecified(settings);

		propertiesChanged();

		Result result = openFilesAndRestore(settings);

		createViewAndFinalize(result.buffer, result.splitConfig, settings);
	} //}}}

