	//{{{ checkJavaVersion() method
	private static void checkJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if (javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version "
				+ javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}
	} //}}}

	//{{{ parseLogLevel() method
	private static int parseLogLevel(String[] args)
	{
		int level = Log.WARNING;
		if (args.length >= 1)
		{
			String levelStr = args[0];
			if (levelStr.length() == 1 && Character.isDigit(levelStr.charAt(0)))
			{
				level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}
		return level;
	} //}}}

	//{{{ parseSettings() method
	private static Settings parseSettings(String[] args)
	{
		Settings s = new Settings();
		s.settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"), ".jedit");
		s.portFile = "server";
		s.restore = true;
		s.gui = true;
		s.noPlugins = false;
		s.noStartupScripts = false;
		s.userDir = System.getProperty("user.dir");
		s.scriptFile = null;

		boolean endOpts = false;
		for (int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if (arg == null)
				continue;
			else if (arg.length() == 0)
				args[i] = null;
			else if (arg.startsWith("-") && !endOpts)
			{
				if (arg.equals("--"))
					endOpts = true;
				else if (arg.equals("-usage"))
				{
					version();
					System.err.println();
					usage();
					System.exit(1);
				}
				else if (arg.equals("-version"))
				{
					version();
					System.exit(1);
				}
				else if (arg.equals("-nosettings"))
					s.settingsDirectory = null;
				else if (arg.startsWith("-settings="))
					s.settingsDirectory = arg.substring(10);
				else if (arg.startsWith("-noserver"))
					s.portFile = null;
				else if (arg.equals("-server"))
					s.portFile = "server";
				else if (arg.startsWith("-server="))
					s.portFile = arg.substring(8);
				else if (arg.startsWith("-background"))
					background = true;
				else if (arg.equals("-nogui"))
					s.gui = false;
				else if (arg.equals("-norestore"))
					s.restore = false;
				else if (arg.equals("-noplugins"))
					s.noPlugins = true;
				else if (arg.equals("-nostartupscripts"))
					s.noStartupScripts = true;
				else if (arg.startsWith("-run="))
					s.scriptFile = arg.substring(5);
				else
				{
					System.err.println("Unknown option: "
						+ arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}

		if (s.settingsDirectory != null && s.portFile != null)
			s.portFile = MiscUtilities.constructPath(s.settingsDirectory, s.portFile);
		else
			s.portFile = null;

		return s;
	} //}}}

	//{{{ connectToServer() method
	private static void connectToServer(Settings s)
	{
		if (s.portFile != null && new File(s.portFile).exists())
		{
			int port, key;
			try
			{
				BufferedReader in = new BufferedReader(new FileReader(s.portFile));
				String check = in.readLine();
				if (!check.equals("b"))
					throw new Exception("Wrong port file format");

				port = Integer.parseInt(in.readLine());
				key = Integer.parseInt(in.readLine());
				in.close();

				Socket socket = new Socket(InetAddress.getByName("127.0.0.1"), port);
				DataOutputStream out = new DataOutputStream(
					socket.getOutputStream());
				out.writeInt(key);

				String script = makeServerScript(s.restore, args, s.scriptFile);

				out.writeUTF(script);

				out.close();

				System.exit(0);
			}
			catch (Exception e)
			{
				Log.log(Log.NOTICE, jEdit.class,
					"An error occurred while connecting to the jEdit server instance.");
				Log.log(Log.NOTICE, jEdit.class,
					"This probably means that jEdit crashed and/or exited abnormally");
				Log.log(Log.NOTICE, jEdit.class,
					"the last time it was run.");
				Log.log(Log.NOTICE, jEdit.class,
					"If you don't know what this means, don't worry.");
				Log.log(Log.NOTICE, jEdit.class, e);
			}
		}
	} //}}}

	//{{{ initSettingsDirectory() method
	private static void initSettingsDirectory(Settings s)
	{
		Writer stream;
		if (s.settingsDirectory != null)
		{
			File _settingsDirectory = new File(s.settingsDirectory);
			if (!_settingsDirectory.exists())
				_settingsDirectory.mkdirs();
			File _macrosDirectory = new File(s.settingsDirectory, "macros");
			if (!_macrosDirectory.exists())
				_macrosDirectory.mkdir();

			String logPath = MiscUtilities.constructPath(
				s.settingsDirectory, "activity.log");

			backupSettingsFile(new File(logPath));

			try
			{
				stream = new BufferedWriter(new FileWriter(logPath));
			}
			catch (Exception e)
			{
				e.printStackTrace();
				stream = null;
			}
		}
		else
		{
			stream = null;
		}
		s.logWriter = stream;
	} //}}}

	//{{{ initServer() method
	private static void initServer(Settings s)
	{
		if (s.portFile != null)
		{
			server = new EditServer(s.portFile);
			if (!server.isOK())
				server = null;
		}
		else
		{
			if (background)
			{
				background = false;
				System.err.println("You cannot specify both the"
					+ " -background and -noserver switches");
			}
		}
	} //}}}

	//{{{ startInitialization() method
	private static void startInitialization(Settings s)
	{
		initMisc();
		initSystemProperties();
		if (jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();

		BeanShell.init();

		initUserProperties();
		initPLAF();

		if (OperatingSystem.hasJava14()
			&& System.getProperty("jedit.nojava14") == null)
		{
			try
			{
				ClassLoader loader = jEdit.class.getClassLoader();
				Class clazz;
				if (loader != null)
					clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
				else
					clazz = Class.forName("org.gjt.sp.jedit.Java14");
				java.lang.reflect.Method meth = clazz
					.getMethod("init", new Class[0]);
				meth.invoke(null, new Object[0]);
			}
			catch (Exception e)
			{
				Log.log(Log.ERROR, jEdit.class, e);
				System.exit(1);
			}
		}

		initActions();
		initDockables();

		GUIUtilities.advanceSplashProgress();

		VFSManager.init();

		if (!s.noPlugins)
			initPlugins();

		if (s.settingsDirectory != null)
		{
			File history = new File(MiscUtilities.constructPath(
				s.settingsDirectory, "history"));
			if (history.exists())
				historyModTime = history.lastModified();
			HistoryModel.loadHistory(history);

			File recent = new File(MiscUtilities.constructPath(
				s.settingsDirectory, "recent.xml"));
			if (recent.exists())
				recentModTime = recent.lastModified();
			BufferHistory.load(recent);
		}

		GUIUtilities.advanceSplashProgress();

		sortBuffers = getBooleanProperty("sortBuffers");
		sortByName = getBooleanProperty("sortByName");

		reloadModes();

		GUIUtilities.advanceSplashProgress();

		SearchAndReplace.load();

		GUIUtilities.advanceSplashProgress();
	} //}}}

	//{{{ startPlugins() method
	private static void startPlugins()
	{
		for (int i = 0; i < jars.size(); i++)
		{
			((EditPlugin.JAR)jars.elementAt(i)).getClassLoader()
				.startAllPlugins();
		}
	} //}}}

	//{{{ loadMacrosAndScripts() method
	private static void loadMacrosAndScripts(Settings s)
	{
		Macros.loadMacros();

		if (!s.noStartupScripts && jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome, "startup");
			File file = new File(path);
			if (file.exists())
				runStartupScripts(file);
		}

		if (!s.noStartupScripts && s.settingsDirectory != null)
		{
			String path = MiscUtilities.constructPath(s.settingsDirectory, "startup");
			File file = new File(path);
			if (!file.exists())
				file.mkdirs();
			else
				runStartupScripts(file);
		}
	} //}}}

	//{{{ runScriptIfSpecified() method
	private static void runScriptIfSpecified(Settings s)
	{
		if (s.scriptFile != null)
		{
			s.scriptFile = MiscUtilities.constructPath(s.userDir, s.scriptFile);
			BeanShell.runScript(null, s.scriptFile, null, false);
		}
	} //}}}

	//{{{ openFilesAndRestore() method
	private static Result openFilesAndRestore(Settings s)
	{
		Result res = new Result();
		res.buffer = openFiles(null, s.userDir, args);

		if (res.buffer != null)
			s.gui = true;

		String splitConfig = null;

		if (s.restore && s.settingsDirectory != null
			&& jEdit.getBooleanProperty("restore")
			&& (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			splitConfig = restoreOpenFiles();
		}

		if (bufferCount == 0 && s.gui)
			newFile(null);

		res.splitConfig = splitConfig;
		return res;
	} //}}}

	//{{{ createViewAndFinalize() method
	private static void createViewAndFinalize(Buffer buffer, String splitConfig, Settings s)
	{
		final Buffer _buffer = buffer;
		final String _splitConfig = splitConfig;
		final boolean _gui = s.gui;

		GUIUtilities.advanceSplashProgress();

		SwingUtilities.invokeLater(new Runnable()
		{
			public void run()
			{
				EditBus.send(new EditorStarted(null));

				if (_gui)
				{
					View view;
					if (_buffer != null)
						view = newView(null, _buffer);
					else
						view = newView(null, _splitConfig);
				}

				// Start I/O threads
				VFSManager.start();

				// Start edit server
				if (server != null)
					server.start();

				GUIUtilities.hideSplashScreen();

				Log.log(Log.MESSAGE, jEdit.class, "Startup "
					+ "complete");

				//{{{ Report any plugin errors
				if (pluginErrors != null)
				{
					String caption = jEdit.getProperty(
						"plugin-error.caption" + (pluginErrors.size() == 1
						? "-1" : ""), new Integer[] {
						new Integer(pluginErrors.size()) });

					new ErrorListDialog(
						jEdit.getFirstView(),
						jEdit.getProperty("plugin-error.title"),
						caption, pluginErrors, true);
					pluginErrors.removeAllElements();
				} //}}}

				// in one case not a single AWT class will
				// have been touched (splash screen off +
				// -nogui -nobackground switches on command
				// line)
				Toolkit.getDefaultToolkit();
			}
		});
	} //}}}

