		setIntegerProperty(name + "style", value.getStyle());
	} //}}}

	//{{{ unsetProperty() method
	/**
	 * Unsets (clears) a property.
	 * @param name The property
	 */
	public static final void unsetProperty(String name)
	{
		if (defaultProps.get(name) != null)
			props.put(name, "");
		else
