private static CommandLineOptions parseCommandLine(String[] args) {
    CommandLineOptions opts = new CommandLineOptions();
    opts.settingsDirectory = MiscUtilities.constructPath(System.getProperty("user.home"),".jedit");
    opts.portFile = "server";
    opts.restore = true;
    opts.gui = true;
    opts.noPlugins = false;
    opts.noStartupScripts = false;
    opts.scriptFile = null;
    opts.background = false;
    boolean endOpts = false;
    String userDir = System.getProperty("user.dir");
    for(int i=0; i<args.length; i++) {
        String arg = args[i];
        if(arg == null) continue;
        else if(arg.length() == 0) args[i] = null;
        else if(arg.startsWith("-") && !endOpts) {
            if(arg.equals("--")) endOpts = true;
            else if(arg.equals("-usage")) { version(); System.err.println(); usage(); System.exit(1); }
            else if(arg.equals("-version")) { version(); System.exit(1); }
            else if(arg.equals("-nosettings")) opts.settingsDirectory = null;
            else if(arg.startsWith("-settings=")) opts.settingsDirectory = arg.substring(10);
            else if(arg.startsWith("-noserver")) opts.portFile = null;
            else if(arg.equals("-server")) opts.portFile = "server";
            else if(arg.startsWith("-server=")) opts.portFile = arg.substring(8);
            else if(arg.startsWith("-background")) opts.background = true;
            else if(arg.equals("-nogui")) opts.gui = false;
            else if(arg.equals("-norestore")) opts.restore = false;
            else if(arg.equals("-noplugins")) opts.noPlugins = true;
            else if(arg.equals("-nostartupscripts")) opts.noStartupScripts = true;
            else if(arg.startsWith("-run=")) opts.scriptFile = arg.substring(5);
            else { System.err.println("Unknown option: "+arg); usage(); System.exit(1); }
            args[i] = null;
        }
    }
    return opts;
}

