import org.gjt.sp.util.Log;
//}}}

/**
 * The main class of the jEdit text editor.
 * @author Slava Pestov
 * @version $Id$
 */
public class jEdit
{
	//{{{ getVersion() method
	/**
	 * Returns the jEdit version as a human-readable string.
	 */
	public static String getVersion()
	{
		return MiscUtilities.buildToVersion(getBuild());
	} //}}}

	//{{{ getBuild() method
	/**
	 * Returns the internal version. MiscUtilities.compareStrings() can be used
	 * to compare different internal versions.
	 */
	public static String getBuild()
	{
		// (major).(minor).(<99 = preX, 99 = final).(bug fix)
		return "04.00.99.01";
	} //}}}

	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		checkJavaVersion();

		CommandLineOptions opts = parseCommandLine(args);

		if (handleServerConnection(opts.portFile, opts.args, opts.scriptFile, opts.restore))
		{
			System.exit(0);
		}

		if (!new File(opts.settingsDirectory, "nosplash").exists())
		{
			GUIUtilities.showSplashScreen();
		}

		background = opts.background;
		initSettingsDirectory(opts.settingsDirectory);
		Log.init(true, opts.level);
		initServer(opts.portFile);
		startApplication(opts, opts.userDir);
	} //}}}

	//{{{ checkJavaVersion() method
	/**
	 * Checks that the Java version is at least 1.3.
	 */
	private static void checkJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if (javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version " + javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}
	} //}}}

	//{{{ CommandLineOptions class
	/**
	 * Holds parsed command line options.
	 */
	private static class CommandLineOptions
	{
		int level;
		String settingsDirectory;
		String portFile;
		boolean restore;
		boolean gui;
		boolean noPlugins;
		boolean noStartupScripts;
		String scriptFile;
		String userDir;
		boolean background;
		String[] args;
	} //}}}

	//{{{ parseCommandLine() method
	/**
	 * Parses command line arguments and returns an options object.
	 */
	private static CommandLineOptions parseCommandLine(String[] args)
	{
		CommandLineOptions opts = new CommandLineOptions();
		opts.level = Log.WARNING;
		if (args.length >= 1)
		{
			String levelStr = args[0];
			if (levelStr.length() == 1 && Character.isDigit(levelStr.charAt(0)))
			{
				opts.level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}
		opts.settingsDirectory = MiscUtilities.constructPath(System.getProperty("user.home"), ".jedit");
		opts.portFile = "server";
		opts.restore = true;
		opts.gui = true;
		opts.noPlugins = false;
		opts.noStartupScripts = false;
		opts.scriptFile = null;
		opts.userDir = System.getProperty("user.dir");
		opts.background = false;
		boolean endOpts = false;
		for (int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if (arg == null)
				continue;
			else if (arg.length() == 0)
				args[i] = null;
			else if (arg.startsWith("-") && !endOpts)
			{
				if (arg.equals("--"))
					endOpts = true;
				else if (arg.equals("-usage"))
				{
					version();
					System.err.println();
					usage();
					System.exit(1);
				}
				else if (arg.equals("-version"))
				{
					version();
					System.exit(1);
				}
				else if (arg.equals("-nosettings"))
					opts.settingsDirectory = null;
				else if (arg.startsWith("-settings="))
					opts.settingsDirectory = arg.substring(10);
				else if (arg.startsWith("-noserver"))
					opts.portFile = null;
				else if (arg.equals("-server"))
					opts.portFile = "server";
				else if (arg.startsWith("-server="))
					opts.portFile = arg.substring(8);
				else if (arg.startsWith("-background"))
					opts.background = true;
				else if (arg.equals("-nogui"))
					opts.gui = false;
				else if (arg.equals("-norestore"))
					opts.restore = false;
				else if (arg.equals("-noplugins"))
					opts.noPlugins = true;
				else if (arg.equals("-nostartupscripts"))
					opts.noStartupScripts = true;
				else if (arg.startsWith("-run="))
					opts.scriptFile = arg.substring(5);
				else
				{
					System.err.println("Unknown option: " + arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}
		if (opts.settingsDirectory != null && opts.portFile != null)
			opts.portFile = MiscUtilities.constructPath(opts.settingsDirectory, opts.portFile);
		else
			opts.portFile = null;
		opts.args = args;
		return opts;
	} //}}}

	//{{{ handleServerConnection() method
	/**
	 * Attempts to connect to a running jEdit instance.
	 */
	private static boolean handleServerConnection(String portFile, String[] args, String scriptFile, boolean restore)
	{
		if (portFile == null)
			return false;
		File port = new File(portFile);
		if (!port.exists())
			return false;
		try
		{
			BufferedReader in = new BufferedReader(new FileReader(port));
			String check = in.readLine();
			if (!"b".equals(check))
				throw new Exception("Wrong port file format");
			int portNum = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();
			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"), portNum);
			DataOutputStream out = new DataOutputStream(socket.getOutputStream());
			out.writeInt(key);
			String script = makeServerScript(restore, args, scriptFile);
			out.writeUTF(script);
			out.close();
			socket.close();
			return true;
		}
		catch (Exception e)
		{
			Log.log(Log.NOTICE, jEdit.class, "An error occurred while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE, jEdit.class, "This probably means that jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE, jEdit.class, "the last time it was run.");
			Log.log(Log.NOTICE, jEdit.class, "If you don't know what this means, don't worry.");
			Log.log(Log.NOTICE, jEdit.class, e);
			return false;
		}
	} //}}}

	//{{{ initSettingsDirectory() method
	/**
	 * Initializes the settings directory and log writer.
	 */
	private static void initSettingsDirectory(String settingsDirectory)
	{
		Writer stream;
		if (settingsDirectory != null)
		{
			File _settingsDirectory = new File(settingsDirectory);
			if (!_settingsDirectory.exists())
				_settingsDirectory.mkdirs();
			File _macrosDirectory = new File(settingsDirectory, "macros");
			if (!_macrosDirectory.exists())
				_macrosDirectory.mkdir();
			String logPath = MiscUtilities.constructPath(settingsDirectory, "activity.log");
			backupSettingsFile(new File(logPath));
			try
			{
				stream = new BufferedWriter(new FileWriter(logPath));
			}
			catch (Exception e)
			{
				e.printStackTrace();
				stream = null;
			}
		}
		else
		{
			stream = null;
		}
		Log.setLogWriter(stream);
		Log.log(Log.NOTICE, jEdit.class, "jEdit version " + getVersion());
		Log.log(Log.MESSAGE, jEdit.class, "Settings directory is " + settingsDirectory);
	} //}}}

	//{{{ initServer() method
	/**
	 * Initializes the edit server if requested.
	 */
	private static void initServer(String portFile)
	{
		if (portFile != null)
		{
			server = new EditServer(portFile);
			if (!server.isOK())
				server = null;
		}
		else
		{
			if (background)
			{
				background = false;
				System.err.println("You cannot specify both the -background and -noserver switches");
			}
		}
	} //}}}

	//{{{ startApplication() method
	/**
	 * Starts the main application after initialization.
	 */
	private static void startApplication(CommandLineOptions opts, String userDir)
	{
		initMisc();
		initSystemProperties();
		if (jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();
		BeanShell.init();
		initUserProperties();
		initPLAF();
		initJava14();
		initActions();
		initDockables();
		GUIUtilities.advanceSplashProgress();
		VFSManager.init();
		if (!opts.noPlugins)
			initPlugins();
		loadHistoryAndRecent(opts.settingsDirectory);
		GUIUtilities.advanceSplashProgress();
		sortBuffers = getBooleanProperty("sortBuffers");
		sortByName = getBooleanProperty("sortByName");
		reloadModes();
		GUIUtilities.advanceSplashProgress();
		SearchAndReplace.load();
		GUIUtilities.advanceSplashProgress();
		startPlugins();
		Macros.loadMacros();
		runStartupScriptsIfNeeded(opts, userDir);
		runScriptIfNeeded(opts, userDir);
		propertiesChanged();
		GUIUtilities.advanceSplashProgress();
		Buffer buffer = openFiles(null, userDir, opts.args);
		if (buffer != null)
			opts.gui = true;
		String splitConfig = null;
		if (opts.restore && opts.settingsDirectory != null && jEdit.getBooleanProperty("restore") && (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			splitConfig = restoreOpenFiles();
		}
		if (bufferCount == 0 && opts.gui)
			newFile(null);
		createViewAndFinish(opts, buffer, splitConfig);
	} //}}}

	//{{{ initJava14() method
	/**
	 * Initializes Java 1.4 specific features if available.
	 */
	private static void initJava14()
	{
		if (OperatingSystem.hasJava14() && System.getProperty("jedit.nojava14") == null)
		{
			try
			{
				ClassLoader loader = jEdit.class.getClassLoader();
				Class clazz;
				if (loader != null)
					clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
				else
					clazz = Class.forName("org.gjt.sp.jedit.Java14");
				java.lang.reflect.Method meth = clazz.getMethod("init", new Class[0]);
				meth.invoke(null, new Object[0]);
			}
			catch (Exception e)
			{
				Log.log(Log.ERROR, jEdit.class, e);
				System.exit(1);
			}
		}
	} //}}}

	//{{{ loadHistoryAndRecent() method
	/**
	 * Loads history and recent files from the settings directory.
	 */
	private static void loadHistoryAndRecent(String settingsDirectory)
	{
		if (settingsDirectory != null)
		{
			File history = new File(MiscUtilities.constructPath(settingsDirectory, "history"));
			if (history.exists())
				historyModTime = history.lastModified();
			HistoryModel.loadHistory(history);
			File recent = new File(MiscUtilities.constructPath(settingsDirectory, "recent.xml"));
			if (recent.exists())
				recentModTime = recent.lastModified();
			BufferHistory.load(recent);
		}
	} //}}}

	//{{{ startPlugins() method
	/**
	 * Starts all loaded plugins.
	 */
	private static void startPlugins()
	{
		for (int i = 0; i < jars.size(); i++)
		{
			((EditPlugin.JAR)jars.elementAt(i)).getClassLoader().startAllPlugins();
		}
	} //}}}

	//{{{ runStartupScriptsIfNeeded() method
	/**
	 * Runs startup scripts if the option is enabled.
	 */
	private static void runStartupScriptsIfNeeded(CommandLineOptions opts, String userDir)
	{
		if (!opts.noStartupScripts && jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome, "startup");
			File file = new File(path);
			if (file.exists())
				runStartupScripts(file);
		}
		if (!opts.noStartupScripts && opts.settingsDirectory != null)
		{
			String path = MiscUtilities.constructPath(opts.settingsDirectory, "startup");
			File file = new File(path);
			if (!file.exists())
				file.mkdirs();
			else
				runStartupScripts(file);
		}
	} //}}}

	//{{{ runScriptIfNeeded() method
	/**
	 * Runs a BeanShell script if specified.
	 */
	private static void runScriptIfNeeded(CommandLineOptions opts, String userDir)
	{
		if (opts.scriptFile != null)
		{
			opts.scriptFile = MiscUtilities.constructPath(userDir, opts.scriptFile);
			BeanShell.runScript(null, opts.scriptFile, null, false);
		}
	} //}}}

	//{{{ createViewAndFinish() method
	/**
	 * Creates the initial view and finalizes startup.
	 */
	private static void createViewAndFinish(CommandLineOptions opts, Buffer buffer, String splitConfig)
	{
		final Buffer _buffer = buffer;
		final String _splitConfig = splitConfig;
		final boolean _gui = opts.gui;
		GUIUtilities.advanceSplashProgress();
		SwingUtilities.invokeLater(new Runnable()
		{
			public void run()
			{
				EditBus.send(new EditorStarted(null));
				if (_gui)
				{
					View view;
					if (_buffer != null)
						view = newView(null, _buffer);
					else
						view = newView(null, _splitConfig);
				}
				VFSManager.start();
				if (server != null)
					server.start();
				GUIUtilities.hideSplashScreen();
				Log.log(Log.MESSAGE, jEdit.class, "Startup complete");
				if (pluginErrors != null)
				{
					String caption = jEdit.getProperty("plugin-error.caption" + (pluginErrors.size() == 1 ? "-1" : ""), new Integer[] { new Integer(pluginErrors.size()) });
					new ErrorListDialog(jEdit.getFirstView(), jEdit.getProperty("plugin-error.title"), caption, pluginErrors, true);
					pluginErrors.removeAllElements();
				}
				Toolkit.getDefaultToolkit();
			}
		});
	} //}}}

	//{{{ Property methods

	//{{{ getProperties() method
	/**
	 * Returns the properties object which contains all known
	 * jEdit properties.
	 * @since jEdit 3.1pre4
	 */
	public static final Properties getProperties()
	{
		return props;
	} //}}}

	//{{{ getProperty() method
	/**
	 * Fetches a property, returning null if it's not defined.
	 * @param name The property
	 */
	public static final String getProperty(String name)
	{
		return props.getProperty(name);
	} //}}}

	//{{{ getProperty() method
	/**
	 * Fetches a property, returning the default value if it's not
	 * defined.
	 * @param name The property
	 * @param def The default value
	 */
	public static final String getProperty(String name, String def)
	{
		return props.getProperty(name, def);
	} //}}}

	//{{{ getProperty() method
	/**
	 * Returns the property with the specified name, formatting it with
	 * the <code>java.text.MessageFormat.format()</code> method.
	 * @param name The property
	 * @param args The positional parameters
	 */
	public static final String getProperty(String name, Object[] args)
	{
		if (name == null)
			return null;
		if (args == null)
			return props.getProperty(name);
		else
		{
			String value = props.getProperty(name);
			if (value == null)
				return null;
			else
				return MessageFormat.format(value, args);
		}
	} //}}}

	//{{{ getBooleanProperty() method
	/**
	 * Returns the value of a boolean property.
	 * @param name The property
	 */
	public static final boolean getBooleanProperty(String name)
	{
		return getBooleanProperty(name, false);
	} //}}}

	//{{{ getBooleanProperty() method
	/**
	 * Returns the value of a boolean property.
	 * @param name The property
	 * @param def The default value
	 */
	public static final boolean getBooleanProperty(String name, boolean def)
	{
		String value = getProperty(name);
		if (value == null)
			return def;
		else if (value.equals("true") || value.equals("yes") || value.equals("on"))
			return true;
		else if (value.equals("false") || value.equals("no") || value.equals("off"))
			return false;
		else
			return def;
	} //}}}

	//{{{ getIntegerProperty() method
	/**
	 * Returns the value of an integer property.
	 * @param name The property
	 * @param def The default value
	 * @since jEdit 4.0pre1
	 */
	public static final int getIntegerProperty(String name, int def)
	{
		String value = getProperty(name);
		if (value == null)
			return def;
		else
		{
			try
			{
				return Integer.parseInt(value);
			}
			catch (NumberFormatException nf)
			{
				return def;
			}
		}
	} //}}}

	//{{{ getFontProperty() method
	/**
	 * Returns the value of a font property. The family is stored
	 * in the <code><i>name</i></code> property, the font size is stored
	 * in the <code><i>name</i>size</code> property, and the font style is
	 * stored in <code><i>name</i>style</code>. For example, if
	 * <code><i>name</i></code> is <code>view.gutter.font</code>,
	 * the properties will be named <code>view.gutter.font</code>,
	 * <code>view.gutter.fontsize</code>, and
	 * <code>view.gutter.fontstyle</code>.
	 *
