	//{{{ reloadModes() method
	/**
	 * Reloads all edit modes.
	 * @since jEdit 3.2pre2
	 */
	public static void reloadModes()
	{
		modes = new Vector(50);
		if (jEditHome == null)
			loadModeCatalog("/modes/catalog", true);
		else
			loadModeCatalog(MiscUtilities.constructPath(jEditHome, "modes", "catalog"), false);
		if (settingsDirectory != null)
		{
			File userModeDir = new File(MiscUtilities.constructPath(settingsDirectory, "modes"));
			if (!userModeDir.exists())
				userModeDir.mkdirs();
			File userCatalog = new File(MiscUtilities.constructPath(settingsDirectory, "modes", "catalog"));
			if (!userCatalog.exists())
			{
				try
				{
					FileWriter out = new FileWriter(userCatalog);
					out.write(jEdit.getProperty("defaultCatalog"));
					out.close();
				}
				catch (IOException io)
				{
					Log.log(Log.ERROR, jEdit.class, io);
				}
			}
			loadModeCatalog(userCatalog.getPath(), false);
		}
		Buffer buffer = buffersFirst;
		while (buffer != null)
		{
			buffer.setMode();
			buffer = buffer.next;
		}
	} //}}}

