	//{{{ saveSettings() method
	/**
	 * Saves all user preferences to disk.
	 */
	public static void saveSettings()
	{
		if (settingsDirectory != null)
		{
			File file1 = new File(MiscUtilities.constructPath(settingsDirectory, "#recent.xml#save#"));
			File file2 = new File(MiscUtilities.constructPath(settingsDirectory, "recent.xml"));
			if (file2.exists() && file2.lastModified() != recentModTime)
			{
				Log.log(Log.WARNING, jEdit.class, file2 + " changed on disk; will not save recent files");
			}
			else
			{
				backupSettingsFile(file2);
				BufferHistory.save(file1);
				file2.delete();
				file1.renameTo(file2);
			}
			recentModTime = file2.lastModified();
			file1 = new File(MiscUtilities.constructPath(settingsDirectory, "#history#save#"));
			file2 = new File(MiscUtilities.constructPath(settingsDirectory, "history"));
			if (file2.exists() && file2.lastModified() != historyModTime)
			{
				Log.log(Log.WARNING, jEdit.class, file2 + " changed on disk; will not save history");
			}
			else
			{
				backupSettingsFile(file2);
				HistoryModel.saveHistory(file1);
				file2.delete();
				file1.renameTo(file2);
			}
			historyModTime = file2.lastModified();
			SearchAndReplace.save();
			Abbrevs.save();
			FavoritesVFS.saveFavorites();
			file1 = new File(MiscUtilities.constructPath(settingsDirectory, "#properties#save#"));
			file2 = new File(MiscUtilities.constructPath(settingsDirectory, "properties"));
			if (file2.exists() && file2.lastModified() != propsModTime)
			{
				Log.log(Log.WARNING, jEdit.class, file2 + " changed on disk; will not save user properties");
			}
			else
			{
				backupSettingsFile(file2);
				try
				{
					OutputStream out = new FileOutputStream(file1);
					props.store(out, "jEdit properties");
					out.close();
				}
				catch (IOException io)
				{
					Log.log(Log.ERROR, jEdit.class, io);
				}
				file2.delete();
				file1.renameTo(file2);
			}
			propsModTime = file2.lastModified();
		}
	} //}}}

	//{{{ exit() method
	/**
	 * Exits cleanly from jEdit, prompting the user if any unsaved files
	 * should be saved first.
	 * @param view The view from which this exit was called
	 * @param reallyExit If background mode is enabled and this parameter
	 * is true, then jEdit will close all open views instead of exiting
	 * entirely.
	 */
	public static void exit(View view, boolean reallyExit)
	{
		VFSManager.waitForRequests();
		EditBus.send(new EditorExitRequested(view));
		reallyExit |= !background;
		saveOpenFiles(view);
		if (!closeAllBuffers(view, reallyExit))
			return;
		if (!reallyExit)
		{
			view = viewsFirst;
			while (view != null)
			{
				closeView(view, false);
				view = view.next;
			}
			saveSettings();
			return;
		}
		view.close();
		Autosave.stop();
		if (server != null)
			server.stopServer();
		EditPlugin[] plugins = getPlugins();
		for (int i = 0; i < plugins.length; i++)
		{
			try
			{
				plugins[i].stop();
			}
			catch (Throwable t)
			{
				Log.log(Log.ERROR, jEdit.class, "Error while stopping plugin:");
				Log.log(Log.ERROR, jEdit.class, t);
			}
		}
		EditBus.send(new EditorExiting(null));
		saveSettings();
		Log.closeStream();
		System.exit(0);
	} //}}}

