		{
			Log.log(Log.DEBUG, jEdit.class, "Loading actions from " + path);
			ActionListHandler ah = new ActionListHandler(path, actionSet);
			XmlParser parser = new XmlParser();
			parser.setHandler(ah);
			parser.parse(null, null, in);
			return true;
